'use client';
import Image from "next/image";
import { useState } from 'react';


export default function Home() {
  const [loading, setLoading] = useState(false);

  const handleRegister = async() => {
    setLoading(true);
    try {
      // Spring Boot 서버로 POST 요청 전송
      const response = await fetch('http://localhost:8080/api/userMembership/register',
      {
        method: 'POST',
        headers : {
          'Content-Type' : 'application/json',
        },
        body : JSON.stringify({
          userId : 2, 
          membershipId : 1
        }),
      });
      console.log(response);
      if (response.ok) {
        alert('Success joining membership')
      } else {
        alert('Join Fail');
      }
    } catch (error) {
      console.error('Network Error', error);
      alert('Unable to connect Network');
    } finally {
      setLoading(false);
    };
  }

  return (
    <div className="flex flex-col flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-black">
      <main className="flex flex-1 w-full max-w-3xl flex-col items-center justify-between py-32 px-16 bg-white dark:bg-black sm:items-start">
        <div className="flex flex-col items-center gap-6 text-center sm:items-start sm:text-left">
          <h1 className="max-w-xs text-3xl font-semibold leading-10 tracking-tight text-black dark:text-zinc-50">
            Welcome to The NEW 2026 BookClub!
            {" "}
          </h1>
          <p className="max-w-lg text-lg leading-8 text-zinc-600 dark:text-zinc-400">
            Please click the below button and join our newest member. {" "}
          </p>
        </div>
        <div className="flex flex-col gap-4 text-base font-medium sm:flex-row">
          <button
            onClick={handleRegister}
            disabled={loading}
            className="flex h-12 w-full items-center justify-center gap-2 rounded-full bg-foreground px-5 text-background transition-colors hover:bg-[#383838] dark:hover:bg-[#ccc] md:w-[158px]"
          >
             <Image
              className="dark:invert h-[14px] w-4"
              src="/vercel.svg"
              alt="Vercel logomark"
              width={16}
              height={14}
            />
            {loading ? 'Processing...' : 'Join'}    
          </button>
        </div>
      </main>
    </div>
  );
}
